"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are expanded in place with the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    real = os.path.realpath(path)
    return parse_lines(_expand(lines, real, (real,)))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())


def _include_target(line):
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != INCLUDE_DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include requires a path")
    return parts[1].strip()


def _expand(lines, path, stack):
    base = os.path.dirname(path)
    out = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            out.append(line)
            continue
        inc = os.path.realpath(os.path.join(base, os.path.expanduser(target)))
        if inc in stack:
            chain = " -> ".join(stack + (inc,))
            raise ConfigError("include cycle detected: {}".format(chain))
        if not os.path.isfile(inc):
            raise ConfigError(
                "included file not found: {} (from {})".format(target, path)
            )
        try:
            with open(inc, "r", encoding="utf-8") as fh:
                inc_lines = fh.read().splitlines()
        except OSError as exc:
            raise ConfigError(
                "cannot read included file {}: {}".format(target, exc)
            ) from exc
        out.extend(_expand(inc_lines, inc, stack + (inc,)))
    return out
